/**
 * tests_detector_parity.js — js/table.js shape mirrors vs rca_core/shape.py.
 *
 * ARCH-REVIEW-2026-11-02 A11. The six "what shape is this payload?"
 * decisions now live in ONE Python module (rca_core/shape.py), but the
 * browser still needs its own copies. Nothing about an untouched copy
 * announces that it should have moved too: the repo has already shipped
 * two real bugs of exactly this shape (a generic_table result classified
 * as an occurrence matrix, and a gated matrix invisible on one side).
 *
 * The expected answers come from Python itself, generated by
 *   python scripts/gen_detector_parity.py
 * and pinned by
 *   python scripts/gen_detector_parity.py --check
 *   python -m pytest tests/test_detector_parity_fixture.py
 *
 * Run: node tests/js/tests_detector_parity.js
 */
'use strict';

const fs = require('fs');
const path = require('path');
const vm = require('vm');

const REPO = path.resolve(__dirname, '..', '..');
const fixture = JSON.parse(fs.readFileSync(
  path.join(REPO, 'tests', 'fixtures', 'detector_parity.json'), 'utf8'));

// js/table.js also references helpers from json-utils.js at load time.
const ctx = { console, TextEncoder, URL, setTimeout, clearTimeout };
ctx.globalThis = ctx;
ctx.window = ctx;
ctx.self = ctx;
ctx.document = undefined;
vm.createContext(ctx);
for (const rel of ['js/json-utils.js', 'js/table.js']) {
  vm.runInContext(fs.readFileSync(path.join(REPO, rel), 'utf8'), ctx,
                  { filename: rel });
}

let passed = 0;
let failed = 0;

function fail(msg) { failed += 1; console.log('FAIL ' + msg); }

for (const [jsName, pyName] of fixture.pairs) {
  if (typeof ctx[jsName] !== 'function') {
    fail(`${jsName} is not defined in js/table.js (Python: shape.${pyName})`);
  }
}

for (const c of fixture.cases) {
  for (const [jsName, expected] of Object.entries(c.expected)) {
    const fn = ctx[jsName];
    if (typeof fn !== 'function') continue;
    let actual;
    try {
      actual = Boolean(fn(c.payload));
    } catch (e) {
      fail(`${c.label} / ${jsName} threw ${e.name}: ${e.message}`);
      continue;
    }
    if (actual !== expected) {
      fail(`${c.label} / ${jsName}: JS=${actual} Python=${expected}`);
    } else {
      passed += 1;
    }
  }
}

console.log(`\n--- detector parity: ${passed} passed, ${failed} failed ` +
            `(${fixture.cases.length} cases x ${fixture.pairs.length} detectors) ---`);
process.exit(failed ? 1 : 0);
